import{_ as e}from"./chunks/multiselect.Gtk6Hii5.js";import{_ as o,o as a,c as r,aa as l}from"./chunks/framework.BAs_AphD.js";const n="/buildary-help-preview/media/cs/tickets/exporty.png",s="/buildary-help-preview/media/cs/tickets/ukol_stazeni.png",b=JSON.parse('{"title":"Export úkolů","description":"","frontmatter":{"title":"Export úkolů","wiki":"cs:tickets:exports"},"headers":[],"relativePath":"tickets/exports.md","filePath":"tickets/exports.md","lastUpdated":1794209661000}'),i={name:"tickets/exports.md"};function d(p,t,k,u,h,c){return a(),r("div",null,[...t[0]||(t[0]=[l('<h1 id="export-ukolu" tabindex="-1">Export úkolů <a class="header-anchor" href="#export-ukolu" aria-label="Permalink to &quot;Export úkolů&quot;">​</a></h1><p>Úkoly stáhnete do Excelu nebo do PDF – všechny zobrazené v seznamu, jen vybrané, nebo jeden úkol. Excel se hodí k dalšímu zpracování dat, PDF k předání a archivaci i s přílohami.</p><p>Krok za krokem: <a href="/buildary-help-preview/akademie/seznam-ukolu">Najít úkoly, filtrovat a exportovat je</a> v Akademii.</p><h2 id="druhy-exportu" tabindex="-1">Druhy exportu <a class="header-anchor" href="#druhy-exportu" aria-label="Permalink to &quot;Druhy exportu&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Export</th><th>Co dostanete</th><th>Přílohy</th></tr></thead><tbody><tr><td><strong>Export Excel</strong></td><td>sešit XLS, úkoly pod sebou a ve sloupcích všechny údaje úkolu – bez ohledu na to, které sloupce máte v mřížce</td><td>žádné</td></tr><tr><td><strong>Export Excel s fotkami</strong></td><td>soubor ZIP se stejným sešitem XLS</td><td>obrázky a fotografie přiložené k úkolům. Jiné soubory a obrázky z vyjádření v ZIP nejsou.</td></tr><tr><td><strong>Export PDF</strong></td><td>PDF, každý úkol začíná na nové stránce, včetně vyjádření</td><td>všechny přílohy úkolů i vyjádření jako přílohy PDF</td></tr><tr><td><strong>Export PDF bez vyjádření</strong></td><td>PDF, každý úkol na nové stránce, bez vyjádření</td><td>vyjádření ani jeho přílohy v PDF nejsou</td></tr></tbody></table><p>Přílohy PDF zobrazíte například v Adobe Acrobat Readeru: v levém panelu klikněte na ikonu sponky.</p><p>Diskuze k úkolu není součástí žádného exportu – viz <a href="/buildary-help-preview/tickets/task_edit#diskuze-a-historie">Řešit a schválit úkol</a>.</p><h2 id="exportovat-zobrazene-ukoly" tabindex="-1">Exportovat zobrazené úkoly <a class="header-anchor" href="#exportovat-zobrazene-ukoly" aria-label="Permalink to &quot;Exportovat zobrazené úkoly&quot;">​</a></h2><ol><li>V Seznamu úkolů nastavte filtry tak, aby se zobrazily úkoly, které chcete stáhnout – viz <a href="/buildary-help-preview/tickets/task_grid">Seznam úkolů a filtry</a>.</li><li>Nad mřížkou klikněte na <strong>Export</strong> a vyberte druh exportu.</li></ol><figure class="shot" style="--w:560px;"><img src="'+n+'" alt="Rozbalené menu Export s volbami Export Excel, Export Excel s fotkami, Export PDF a Export PDF bez vyjádření" loading="lazy"></figure><p>Stáhnou se úkoly, které jsou v mřížce právě zobrazené.</p><h2 id="exportovat-vybrane-ukoly" tabindex="-1">Exportovat vybrané úkoly <a class="header-anchor" href="#exportovat-vybrane-ukoly" aria-label="Permalink to &quot;Exportovat vybrané úkoly&quot;">​</a></h2><ol><li>Zaškrtněte v mřížce úkoly, které chcete stáhnout.</li><li>Klikněte na počet vybraných úkolů v záhlaví mřížky a vyberte druh exportu.</li></ol><figure class="shot" style="--w:600px;"><img src="'+e+'" alt="Tři vybrané úkoly a rozbalená nabídka hromadných operací s exporty" loading="lazy"></figure><h2 id="stahnout-jeden-ukol-do-pdf" tabindex="-1">Stáhnout jeden úkol do PDF <a class="header-anchor" href="#stahnout-jeden-ukol-do-pdf" aria-label="Permalink to &quot;Stáhnout jeden úkol do PDF&quot;">​</a></h2><p>Jeden úkol stáhnete jako PDF volbou <strong>Stažení do PDF</strong>:</p><ul><li>v detailu úkolu v menu <strong>⋮</strong> vpravo nahoře,</li><li>v Kanbanu v menu <strong>⋮</strong> na kartičce úkolu.</li></ul><figure class="shot" style="--w:560px;"><img src="'+s+'" alt="Menu v detailu úkolu s vyznačenou volbou Stažení do PDF" loading="lazy"></figure>',18)])])}const x=o(i,[["render",d]]);export{b as __pageData,x as default};
